{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "CC-292, a covalent BTK inhibitor sharing the acrylamide and aminopyrimidine core with the query, showed excellent oral bioavailability in a Phase IA human study, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Rilzabrutinib, another oral covalent BTK inhibitor, had absolute oral bioavailability <5% in healthy subjects, providing a counterexample; however, its cyanoacrylamide warhead and larger lipophilic structure differ from the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C22"],
      "claim": "Sunitinib in humans has moderate oral bioavailability around 50%, supporting that kinase-inhibitor-like oral drugs with similar physicochemical properties can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Tegoprazan showed 86–100% oral bioavailability in humans, a high-F example, though structurally unrelated and of lower transferability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Lisofylline had only 5.9% oral bioavailability in humans, a low-F example, but its structure is dissimilar and does not override the more relevant BTK-inhibitor evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a covalent BTK inhibitor with an acrylamide warhead and aminopyrimidine scaffold. The most structurally relevant human evidence, CC-292, demonstrates excellent oral bioavailability in this chemotype. Although rilzabrutinib shows low F in the same target class, its distinct warhead and lipophilic architecture limit transfer. Multiple additional oral drugs with moderate-to-high F support that the query's properties are compatible with F ≥ 20%. Therefore predict high.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the exact query molecule.",
    "Morgan similarities are low (0.21–0.23), making structural transfer uncertain.",
    "Conflicting human F data within the covalent BTK inhibitor class require cautious interpretation."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

